import{_ as a,o,c,a5 as r}from"./chunks/framework.CXvGqWf0.js";const u=JSON.parse('{"title":"漫画 · 第 64 话 cascade layers 与 @scope 的工程用法","description":"","frontmatter":{},"headers":[],"relativePath":"comics/architecture/EP.64-cascade-layers-scope.md","filePath":"comics/architecture/EP.64-cascade-layers-scope.md","lastUpdated":1793853676000}'),t={name:"comics/architecture/EP.64-cascade-layers-scope.md"};function s(d,e,l,i,n,h){return o(),c("div",null,[...e[0]||(e[0]=[r('<h1 id="漫画-·-第-64-话-cascade-layers-与-scope-的工程用法" tabindex="-1">漫画 · 第 64 话 cascade layers 与 @scope 的工程用法 <a class="header-anchor" href="#漫画-·-第-64-话-cascade-layers-与-scope-的工程用法" aria-label="Permalink to &quot;漫画 · 第 64 话 cascade layers 与 @scope 的工程用法&quot;">​</a></h1><blockquote><p>对应正文：<a href="./../../docs/architecture/02-cascade-layers-scope">docs/architecture/02-cascade-layers-scope.md</a> ｜ 原画：<a href="./EP.64-cascade-layers-scope.svg">EP.64-cascade-layers-scope.svg</a></p></blockquote><h2 id="登场角色" tabindex="-1">登场角色 <a class="header-anchor" href="#登场角色" aria-label="Permalink to &quot;登场角色&quot;">​</a></h2><ul><li><strong>标签君</strong>：结构师。本话他接手一套「覆盖按钮要写四层选择器」的中台项目。</li><li><strong>像素酱</strong>：CSS 造型师。她习惯用更长选择器和 <code>!important</code> 解决问题，被层顺序上了一课。</li></ul><h2 id="剧情梗概" tabindex="-1">剧情梗概 <a class="header-anchor" href="#剧情梗概" aria-label="Permalink to &quot;剧情梗概&quot;">​</a></h2><p>项目同时引入 UI 库、业务组件和全局样式。为了改一个按钮颜色，代码里写着 <code>.page .card .button.button--primary</code>，仍偶尔被库里的 <code>!important</code> 压住。标签君声明四层 <code>reset, vendor, components, utilities</code>，把库放进 vendor 层，用 <code>@scope</code> 限定页面级覆盖。覆盖特异性从 0-4-0 降到 0-1-0。</p><h2 id="分格解读" tabindex="-1">分格解读 <a class="header-anchor" href="#分格解读" aria-label="Permalink to &quot;分格解读&quot;">​</a></h2><h3 id="格1-·-痛点现场" tabindex="-1">格1 · 痛点现场 <a class="header-anchor" href="#格1-·-痛点现场" aria-label="Permalink to &quot;格1 · 痛点现场&quot;">​</a></h3><p>没有层时，优先级只有两个旋钮：特异性和源码顺序。两个团队各自加长选择器，最终形成军备竞赛。第三方库的 <code>!important</code> 更是无法用普通规则覆盖，只能继续加 <code>!important</code>。</p><h3 id="格2-·-机制登场" tabindex="-1">格2 · 机制登场 <a class="header-anchor" href="#格2-·-机制登场" aria-label="Permalink to &quot;格2 · 机制登场&quot;">​</a></h3><p><code>@layer</code> 把优先级变成可声明的顺序：层间先比层顺序，再比特异性；未分层样式高于所有层。三个容易踩的规则是——顺序由首次声明决定；未分层样式最高；层内 <code>!important</code> 顺序反向。<code>@scope</code> 则给选择器加边界，把样式限制在根的子树内，并在多重作用域命中时按「就近原则」胜出。</p><h3 id="格3-·-落地收束" tabindex="-1">格3 · 落地收束 <a class="header-anchor" href="#格3-·-落地收束" aria-label="Permalink to &quot;格3 · 落地收束&quot;">​</a></h3><p>标签君把所有入口的层顺序集中声明一次，第三方库用 <code>@import ... layer(vendor)</code> 导入，业务组件进 components 层，工具类进 utilities 层，页面级覆盖用 <code>@scope (.page-shell)</code> 包住。<code>!important</code> 数量下降八成，跨路由泄漏归零。</p><h2 id="码叔划重点" tabindex="-1">码叔划重点 <a class="header-anchor" href="#码叔划重点" aria-label="Permalink to &quot;码叔划重点&quot;">​</a></h2><ol><li>分层后先比层顺序，再比特异性，长选择器不再是主要武器。</li><li>未分层样式优先级最高，迁移时先给遗留样式加层。</li><li>层内 <code>!important</code> 反向：低层的 <code>!important</code> 反而更高，这不是 bug。</li><li><code>@scope</code> 不改变特异性，只加边界；多作用域命中时更近的根胜出。</li><li><code>@scope</code> 兼容性仍在推进，需保留 <code>.card h2</code> 等价规则兜底。</li></ol><h2 id="自测一题" tabindex="-1">自测一题 <a class="header-anchor" href="#自测一题" aria-label="Permalink to &quot;自测一题&quot;">​</a></h2><p><strong>问</strong>：已经用了 <code>@layer</code>，为什么线上仍有一部分样式覆盖不掉？</p><p><strong>答</strong>：先检查这些规则是否「未分层」。未分层样式优先级高于所有分层样式，所以遗留全局样式会压过层内规则。迁移期应先把它们收编进某个层，层顺序才会真正生效。另一个检查点是层内 <code>!important</code>——它的顺序与普通声明相反，低层反而更高。</p><h2 id="动手实验" tabindex="-1">动手实验 <a class="header-anchor" href="#动手实验" aria-label="Permalink to &quot;动手实验&quot;">​</a></h2><ul><li>在示例中拖动层顺序，观察同一个按钮的最终颜色翻转：<a href="./../../examples/architecture/02-cascade-layers-scope">examples/architecture/02-cascade-layers-scope</a></li><li>切换 <code>@scope</code> 开关，对比卡片内标题是否被外部规则污染。</li></ul><h2 id="下一话预告" tabindex="-1">下一话预告 <a class="header-anchor" href="#下一话预告" aria-label="Permalink to &quot;下一话预告&quot;">​</a></h2><p>第 65 话《主题与明暗体系的构建》——明暗不是再写一套颜色，而是一套语义映射加一个切换契约。</p>',22)])])}const m=a(t,[["render",s]]);export{u as __pageData,m as default};
